	ErrGitHubServerError  ErrorCode = "GITHUB_SERVER_ERROR"

	// Parser errors.
	ErrParserInvalidYAML  ErrorCode = "PARSER_INVALID_YAML"
	ErrParserMissingField ErrorCode = "PARSER_MISSING_FIELD"
	ErrParserUnexpected   ErrorCode = "PARSER_UNEXPECTED"

	// Database errors.
	ErrDatabaseConnection  ErrorCode = "DATABASE_CONNECTION"
	ErrDatabaseQuery       ErrorCode = "DATABASE_QUERY"
	ErrDatabaseTransaction ErrorCode = "DATABASE_TRANSACTION"
	ErrDatabaseNotFound    ErrorCode = "DATABASE_NOT_FOUND"

	// Adapter errors.
	ErrAdapterInternal ErrorCode = "ADAPTER_INTERNAL"
	ErrAdapterTimeout  ErrorCode = "ADAPTER_TIMEOUT"

	// Validation errors.
	ErrValidationInvalidURL   ErrorCode = "VALIDATION_INVALID_URL"
	ErrValidationMissingInput ErrorCode = "VALIDATION_MISSING_INPUT"
)

// SourceError is the normalized error shape for all backend errors.
// It carries a machine-readable code, a user-facing message, the error source,
// a retryability hint, and an optional path for file-level errors.
type SourceError struct {
	Code      ErrorCode   `json:"code"`
	Message   string      `json:"message"`
	Source    ErrorSource `json:"source"`
	Retryable bool        `json:"retryable"`
	Path      string      `json:"path,omitempty"`
}

func (e SourceError) Error() string {
	if e.Path != "" {
		return fmt.Sprintf("[%s/%s] %s (path: %s)", e.Source, e.Code, e.Message, e.Path)
	}
	return fmt.Sprintf("[%s/%s] %s", e.Source, e.Code, e.Message)
}

// NewGitHubRateLimitError returns a SourceError for GitHub rate limit responses.
func NewGitHubRateLimitError(retryAfterMsg string) SourceError {
	msg := "GitHub API rate limit reached."
	if retryAfterMsg != "" {
		msg += " " + retryAfterMsg
	}
	return SourceError{
		Code:      ErrGitHubRateLimit,
		Message:   msg,
		Source:    ErrorSourceGitHub,
		Retryable: true,
	}
}

// NewGitHubNotFoundError returns a SourceError for inaccessible or missing repos.
func NewGitHubNotFoundError(repoURL string) SourceError {
	return SourceError{
		Code:      ErrGitHubNotFound,
		Message:   fmt.Sprintf("Repository not found or inaccessible: %s", repoURL),
		Source:    ErrorSourceGitHub,
		Retryable: false,
	}
}

// NewGitHubNetworkError returns a SourceError for transient network failures.
func NewGitHubNetworkError(detail string) SourceError {
	return SourceError{
		Code:      ErrGitHubNetworkError,
		Message:   fmt.Sprintf("GitHub API request failed: %s", detail),
		Source:    ErrorSourceGitHub,
		Retryable: true,
	}
}

// NewParserInvalidYAMLError returns a SourceError for YAML parse failures.
func NewParserInvalidYAMLError(path, detail string) SourceError {
	return SourceError{
		Code:      ErrParserInvalidYAML,
		Message:   fmt.Sprintf("Invalid YAML in %s: %s", path, detail),
		Source:    ErrorSourceParser,
		Retryable: false,
		Path:      path,
	}
}

// NewValidationError returns a SourceError for input validation failures.
func NewValidationError(code ErrorCode, message string) SourceError {
	return SourceError{
		Code:      code,
		Message:   message,
		Source:    ErrorSourceValidation,
		Retryable: false,
	}
}

// NewDatabaseError returns a SourceError for database failures.
func NewDatabaseError(code ErrorCode, detail string) SourceError {
	return SourceError{
		Code:      code,
		Message:   fmt.Sprintf("Database error: %s", detail),
		Source:    ErrorSourceDatabase,
		Retryable: true,
	}
}

// APIError is the HTTP response body for error responses.
type APIError struct {
	Code       ErrorCode   `json:"code"`
	Message    string      `json:"message"`
	Source     ErrorSource `json:"source"`
	Retryable  bool        `json:"retryable"`
	CachedData interface{} `json:"cached_data,omitempty"`
}

// FromSourceError converts a SourceError to an APIError.
func FromSourceError(e SourceError, cachedData interface{}) APIError {
	return APIError{
		Code:       e.Code,
		Message:    e.Message,
		Source:     e.Source,
		Retryable:  e.Retryable,
		CachedData: cachedData,
	}
}
package domain

import "time"

// SyncStatus reflects the outcome of a workspace sync run.
type SyncStatus string

const (
	SyncStatusRunning SyncStatus = "running"
	SyncStatusSuccess SyncStatus = "success"
	SyncStatusPartial SyncStatus = "partial"
	SyncStatusFailed  SyncStatus = "failed"
	SyncStatusSkipped SyncStatus = "skipped"
)

// SyncRun is a record of a single sync attempt stored in workspace_sync_runs.
type SyncRun struct {
	ID          string
	WorkspaceID string
	Trigger     string
	Mode        string
	Status      SyncStatus
	CommitSHA   string
	StartedAt   time.Time
	FinishedAt  *time.Time
	ErrorCode   string
	ErrorMsg    string
}

// StaleThreshold is the duration after which a successful sync is considered stale.
// Configurable at runtime; the default is 30 minutes.
const DefaultStaleThreshold = 30 * time.Minute

// DeriveSourceState computes a SourceState from the latest SyncRun.
// When latestRun is nil, the workspace has never been synced — SourceState is stale.
func DeriveSourceState(latestRun *SyncRun, staleThreshold time.Duration) SourceState {
	if latestRun == nil {
		return SourceState{Stale: true}
	}

	switch latestRun.Status {
	case SyncStatusFailed:
		return SourceState{
			Stale:        true,
			LastSyncedAt: latestRun.FinishedAt,
			ErrorCode:    latestRun.ErrorCode,
			ErrorMessage: latestRun.ErrorMsg,
		}
	case SyncStatusSuccess, SyncStatusPartial:
		if latestRun.FinishedAt == nil {
			return SourceState{Stale: true}
		}
		age := time.Since(*latestRun.FinishedAt)
		return SourceState{
			Stale:        age > staleThreshold,
			LastSyncedAt: latestRun.FinishedAt,
		}
	case SyncStatusRunning:
		// A sync is in progress — report the previous sync state as current.
		// Caller can detect this by checking ErrorCode == "" and Stale == false
		// with a non-nil LastSyncedAt near now.
		return SourceState{
			Stale:        false,
			LastSyncedAt: &latestRun.StartedAt,
		}
	default:
		return SourceState{Stale: true}
	}
}

// FreshState returns a non-stale SourceState with the given sync time.
func FreshState(syncedAt time.Time) SourceState {
	t := syncedAt
	return SourceState{
		Stale:        false,
		LastSyncedAt: &t,
	}
}

// StaleState returns a stale SourceState with an optional last-synced time.
func StaleState(syncedAt *time.Time) SourceState {
	return SourceState{
		Stale:        true,
		LastSyncedAt: syncedAt,
	}
}

// UnavailableState returns a stale SourceState with an error indicating the data is unavailable.
func UnavailableState(code, message string) SourceState {
	return SourceState{
		Stale:        true,
		ErrorCode:    code,
		ErrorMessage: message,
	}
}

// FailedState returns a stale SourceState reflecting a failed sync attempt.
func FailedState(syncedAt *time.Time, code, message string) SourceState {
	return SourceState{
		Stale:        true,
		LastSyncedAt: syncedAt,
		ErrorCode:    code,
		ErrorMessage: message,
	}
}

