// ListActivityEvents returns activity events for a workspace filtered by scope.
func (r *Reader) ListActivityEvents(ctx context.Context, workspaceID pgtype.UUID, featureID, taskID string) ([]WorkspaceActivityEvent, error) {
	var (
		q    string
		args []interface{}
	)
	switch {
	case taskID != "" && featureID != "":
		q = `
			SELECT id, workspace_id, scope_type, feature_id, task_id, action, actor,
			       occurred_at, note, sequence, raw_event, created_at
			FROM workspace_activity_events
			WHERE workspace_id = $1 AND feature_id = $2 AND task_id = $3
			ORDER BY occurred_at DESC, sequence DESC`
		args = []interface{}{workspaceID, featureID, taskID}
	case featureID != "":
		q = `
			SELECT id, workspace_id, scope_type, feature_id, task_id, action, actor,
			       occurred_at, note, sequence, raw_event, created_at
			FROM workspace_activity_events
			WHERE workspace_id = $1 AND feature_id = $2
			ORDER BY occurred_at DESC, sequence DESC`
		args = []interface{}{workspaceID, featureID}
	default:
		q = `
			SELECT id, workspace_id, scope_type, feature_id, task_id, action, actor,
			       occurred_at, note, sequence, raw_event, created_at
			FROM workspace_activity_events
			WHERE workspace_id = $1
			ORDER BY occurred_at DESC, sequence DESC`
		args = []interface{}{workspaceID}
	}

	rows, err := r.db.Query(ctx, q, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []WorkspaceActivityEvent
	for rows.Next() {
		var e WorkspaceActivityEvent
		if err := rows.Scan(
			&e.ID, &e.WorkspaceID, &e.ScopeType, &e.FeatureID, &e.TaskID,
			&e.Action, &e.Actor, &e.OccurredAt, &e.Note,
			&e.Sequence, &e.RawEvent, &e.CreatedAt,
		); err != nil {
			return nil, err
		}
		out = append(out, e)
	}
	return out, rows.Err()
}

// CountFeatureTasks returns task status counts for a feature.
func (r *Reader) CountFeatureTasks(ctx context.Context, workspaceID pgtype.UUID, featureID string) (map[string]int, error) {
	const q = `
		SELECT status, count(*) as cnt
		FROM workspace_tasks
		WHERE workspace_id = $1 AND feature_id = $2
		GROUP BY status`
	rows, err := r.db.Query(ctx, q, workspaceID, featureID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	counts := make(map[string]int)
	for rows.Next() {
		var status *string
		var cnt int
		if err := rows.Scan(&status, &cnt); err != nil {
			return nil, err
		}
		key := ""
		if status != nil {
			key = *status
		}
		counts[key] = cnt
	}
	return counts, rows.Err()
}

// --- helpers ---

func parseUUID(s string) (pgtype.UUID, error) {
	var uid pgtype.UUID
	if err := uid.Scan(s); err != nil {
		return pgtype.UUID{}, err
	}
	return uid, nil
}

func uuidStr(u pgtype.UUID) string {
	if !u.Valid {
		return ""
	}
	b := u.Bytes
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
		b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func derefStr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

type scannable interface {
	Scan(dest ...any) error
}

func scanSyncRun(row scannable, s *WorkspaceSyncRun) error {
	return row.Scan(
		&s.ID, &s.WorkspaceID, &s.Trigger, &s.Branch, &s.FeatureID, &s.TaskID,
		&s.Mode, &s.Status, &s.CommitSha, &s.ChangedPaths,
		&s.StartedAt, &s.FinishedAt, &s.ErrorCode, &s.ErrorMessage, &s.Metadata,
	)
}

func scanFeature(row scannable, f *WorkspaceFeature) error {
	return row.Scan(
		&f.ID, &f.WorkspaceID, &f.FeatureID, &f.Title, &f.FeatureStatus, &f.CurrentStage,
		&f.NextAction, &f.Stages, &f.SourcePath, &f.SourceHash, &f.CreatedAt, &f.UpdatedAt,
	)
}

func scanTask(row scannable, t *WorkspaceTask) error {
	return row.Scan(
		&t.ID, &t.WorkspaceID, &t.FeatureID, &t.TaskID, &t.Title, &t.Repo, &t.Status,
		&t.DependsOn, &t.BlockedReason, &t.Branch, &t.Execution, &t.Pr, &t.WorkspacePr,
		&t.SourcePath, &t.SourceHash, &t.CreatedAt, &t.UpdatedAt,
	)
}

